#ifdef CONFIG_ARCH_CKMMU
#define LOAD_KERNEL_ADDR        (DRAMBASE + 0x00000000)	/* ckmmu get entry address from offset 0 */
#elif defined(CONFIG_ARCH_ARM)
#define LOAD_KERNEL_ADDR        (DRAMBASE + 0x00008000) /* arm get entry address from offset 0x8000 */
#else
#ifdef CONFIG_ENABLE_LINUX
#define LOAD_KERNEL_ADDR        (DRAMBASE + 0x00008000) /* boot 3200 linux image */
#else
#define LOAD_KERNEL_ADDR        (DRAMBASE + 0x00040000) /* NOTE: don't modify this */
#endif
#endif

#define DETECT_DRAM64_BASE      (DRAMBASE + 0x00800000)
#define DETECT_DRAM128_BASE     (DRAMBASE + 0x01000000)
#define DETECT_DRAM256_BASE     (DRAMBASE + 0x02000000)
#define DETECT_DRAM512_BASE     (DRAMBASE + 0x04000000)
#define DETECT_DRAM1024_BASE    (DRAMBASE + 0x08000000)
#define DETECT_DRAM2048_BASE    (DRAMBASE + 0x10000000)

/* the size of kernel after decompressed must < DECOMPRESS_OUTPUT_MAX_SIZE
 * otherwise inflate() will return -5 */
#define DECOMPRESS_OUTPUT_MAX_SIZE   (KERNEL_END_ADDR - LOAD_KERNEL_ADDR)

/* Right after bootloader, free memory start */
