#define FM_IRQHANDLER_STACKTOP_UNDEF 0x00100000
#define FM_IRQHANDLER_STACKTOP_SYS   0x000f0000 /* defined, but never used */
#define FM_IRQHANDLER_STACKTOP_IRQ   0x00080000
#define FM_IRQHANDLER_STACKTOP_FIQ   0x00088000
#define FM_DRM                       0x00058000
#define FM_BOOTLOADER_CODE           0x00060000

#define LOADER_RESERVED         (FM_RESERVED)
#define FMEM_START              (DRAMBASE + LOADER_RESERVED)
