#define CONFIG_DRAMSIZE_0(s)            (s)
#define CONFIG_DRAMSIZE_1(s)            ((s) << 8)
#define CONFIG_DRAMSIZE_2(s)            ((s) << 16)
#define CONFIG_DRAMSIZE(s0, s1)         (CONFIG_DRAMSIZE_0(s0) | CONFIG_DRAMSIZE_1(s1))
#define CONFIG_GETDRAMSIZE_PARAM(x, n)  (((x) >> ((n) << 3)) & 0xff)
#define CONFIG_GETDRAMSIZE(x, n)        ((CONFIG_GETDRAMSIZE_PARAM(x, n) == 0) ? 0 : (1 << CONFIG_GETDRAMSIZE_PARAM(x, n)))

// boot flag (32 bits)
// bits [0..1] : boot flag
// bits [2..5]   : first boot media
//       2..4    : boot media
//          5    : encrypted flag
// bits [6..9]   : second boot media
//       6..8    : boot media
//          9    : encrypted flag
// bits [10..12] : load flag
#define BOOTFLAG_NONE           0x00    // do not boot automatically
#define BOOTFLAG_BOOT           0x01    // boot by the order of boot media
#define BOOTFLAG_DIRECT         0x02    // do not enter boot prompt mode
#define BOOTFLAG_RETRY          0x10000 // retry until it successes

#define BOOTFLAG_MEDIA_BITS     0x04    // bits assigned for boot media
#define BOOTFLAG_MEDIA_MASK     0x0F    // bitmask for boot media flags

#define BOOTFLAG_MEDIA_NONE     0x00    // No boot media
#define BOOTFLAG_MEDIA_FLASH    0x01    // ROM (FlexROM or Parallel Flash)
#define BOOTFLAG_MEDIA_NETWORK  0x04    // Network (TFTP)
#define BOOTFLAG_MEDIA_NOP      0x05    // do nothing (infinite loop)

#define BOOTFLAG_LOAD_NONE		0x00    // No load
#define BOOTFLAG_LOAD_IRQHANDLER	0x01    // Load irqhandler
#define BOOTFLAG_LOAD_BITMAP		0x02    // Load bitmaps
#define BOOTFLAG_LOAD_DVI		0x10    // Load ucode
#define BOOTFLAG_LOAD_MASK		0x0f
#define MAX_USERPREF_SIZE		0x10000 // 64KB max.

#define BOOTFLAG_BOOT_FIRST(x)  ((x) << 2)
#define BOOTFLAG_BOOT_SECOND(x) ((x) << 6)
#define BOOTFLAG_LOAD(x)        ((x) << 10)

#ifndef __ASSEMBLY__
//
// Kernel parameter
//

#define VECTORS_SIZE   0x200

// from Linux source : include/asm-arm/setup.h
/* The list ends with an ATAG_NONE node. */
#define ATAG_NONE   0x00000000

struct tag_header {
	unsigned int size;	//unit:word(4bytes)
	unsigned int tag;
};

/* The list must start with an ATAG_CORE node */
#define ATAG_CORE   0x54410001

struct tag_core {
	unsigned int flags;      /* bit 0 = read-only */
	unsigned int pagesize;
	unsigned int rootdev;
};

/* it is allowed to have multiple ATAG_MEM nodes */
#define ATAG_MEM    0x54410002

struct tag_mem32 {
	unsigned int size;
	unsigned int start;  /* physical start address */
};

/* VGA text type displays */
#define ATAG_VIDEOTEXT  0x54410003

struct tag_videotext {
	unsigned char      x;
	unsigned char      y;
	unsigned short     video_page;
	unsigned char      video_mode;
	unsigned char      video_cols;
	unsigned short     video_ega_bx;
	unsigned char      video_lines;
	unsigned char      video_isvga;
	unsigned short     video_points;
};

/* describes how the ramdisk will be used in kernel */
#define ATAG_RAMDISK    0x54410004

struct tag_ramdisk {
	unsigned int flags;  /* bit 0 = load, bit 1 = prompt */
	unsigned int size;   /* decompressed ramdisk size in _kilo_ bytes */
	unsigned int start;  /* starting block of floppy-based RAM disk image */
};

/*
 *  this one accidentally used virtual addresses - as such,
 *  its depreciated.
 */
#define ATAG_INITRD 0x54410005

/* describes where the compressed ramdisk image lives (physical address) */
#define ATAG_INITRD2    0x54420005

struct tag_initrd {
	unsigned int start;  /* physical start address */
	unsigned int size;   /* size of compressed ramdisk image in bytes */
};

/* board serial number. "64 bits should be enough for everybody" */
#define ATAG_SERIAL 0x54410006

struct tag_serialnr {
	unsigned int low;
	unsigned int high;
};

/* board revision */
#define ATAG_REVISION   0x54410007

struct tag_revision {
	unsigned int rev;
};

/* initial values for vesafb-type framebuffers. see struct screen_info
 * in include/linux/tty.h
 */
#define ATAG_VIDEOLFB   0x54410008

struct tag_videolfb {
	unsigned short     lfb_width;
	unsigned short     lfb_height;
	unsigned short     lfb_depth;
	unsigned short     lfb_linelength;
	unsigned int       lfb_base;
	unsigned int       lfb_size;
	unsigned char      red_size;
	unsigned char      red_pos;
	unsigned char      green_size;
	unsigned char      green_pos;
	unsigned char      blue_size;
	unsigned char      blue_pos;
	unsigned char      rsvd_size;
	unsigned char      rsvd_pos;
};

/* command line: \0 terminated string */
#define ATAG_CMDLINE    0x54410009

struct tag_cmdline {
	char    cmdline[1];     /* this is the minimum size */
};

/* acorn RiscPC specific information */
#define ATAG_ACORN  0x41000101

struct tag_acorn {
	unsigned int memc_control_reg;
	unsigned int vram_pages;
	unsigned char sounddefault;
	unsigned char adfsdrives;
};

/* footbridge memory clock, see arch/arm/mach-footbridge/arch.c */
#define ATAG_MEMCLK 0x41000402

struct tag_memclk {
	unsigned int fmemclk;
};

struct tag {
	struct tag_header hdr;
	union {
		struct tag_core       core;
		struct tag_mem32      mem;
		struct tag_videotext  videotext;
		struct tag_ramdisk    ramdisk;
		struct tag_initrd     initrd;
		struct tag_serialnr   serialnr;
		struct tag_revision   revision;
		struct tag_videolfb   videolfb;
		struct tag_cmdline    cmdline;
		struct tag_acorn      acorn;    /*Acorn specific*/
		struct tag_memclk     memclk;   /*DC21285 specific*/
	} u;
};

#define tag_size(type)  ((sizeof(struct tag_header) + sizeof(struct type)) >> 2)
#define tag_next(t) ((struct tag *)((u32 *)(t) + (t)->hdr.size))

#endif  // __ASSEMBLY__

